var machine = getMachine((await listMachines())[0].id)
await machine.waitAndAcquire()
var page = await machine.browser.newtab("https://github.com/browser-use/browser-use/issues")
await wait({ waitTime: 3 })
var snap = await page.snapshot()
console.log(snap.snapshot.outline())

// Click enhancement label in the dialog
await page.click({ ref: "e1146" })
await wait({ waitTime: 3 })
var snap = await page.snapshot()
console.log(snap.snapshot.outline())

// Click the enhancement option to select it
await page.click({ ref: "e1146" })
await wait({ waitTime: 2 })
// Check the URL to see what happened
var url = await page.url()
console.log("Current URL:", url)
var snap = await page.snapshot()
console.log(snap.snapshot.outline())

// Check the outline for the labels dialog content more carefully
var snap = await page.snapshot()
// Find any dialog close or apply buttons
console.log(snap.snapshot.grep("dialog", { context: 5 }))
console.log(snap.snapshot.grep("enhancement", { context: 3 }))

var snap = await page.snapshot()
// Look for any apply/close button and the sort dropdown
console.log(snap.snapshot.grep("dialog", { context: 10 }))
console.log("---")
console.log(snap.snapshot.grep("Sort", { context: 3 }))
console.log("---")
console.log(snap.snapshot.grep("Apply", { context: 3 }))
console.log("---")
// Look for the labels bar
console.log(snap.snapshot.grep("is:issue", { context: 5 }))

var snap = await page.snapshot()
// Look at the labels dialog content
console.log(snap.snapshot.grep("enhancement", { context: 5 }))
console.log("---")
// Look for any buttons or close elements in the dialog
console.log(snap.snapshot.grep("e114", { context: 2 }))

// Press Escape to close the dialog
await page.press({ key: "Escape" })
await wait({ waitTime: 2 })
var snap = await page.snapshot()
// Look at the area near the search/filter bar for labels
console.log(snap.snapshot.grep("Labels", { context: 3 }))
console.log("---")
console.log(snap.snapshot.grep("is:issue", { context: 10 }))
console.log("---")
console.log(snap.snapshot.grep("Sort", { context: 5 }))

// Clear the search field and type the filter
await page.click({ ref: "e244" })
await wait({ waitTime: 1 })
// Clear existing text and type our search
await page.type({ ref: "e244", text: "is:issue state:open label:enhancement sort:updated-desc", clear: true })
await wait({ waitTime: 1 })
await page.press({ key: "Enter" })
await wait({ waitTime: 3 })
var url = await page.url()
console.log("Current URL:", url)
var snap = await page.snapshot()
console.log(snap.snapshot.outline())

// Let me get a more detailed view of the issues area
var snap = await page.snapshot()
// Look at the issues area more carefully
console.log(snap.snapshot.grep("opened on", { context: 3 }))
console.log("===")
console.log(snap.snapshot.grep("/issues/", { context: 2 }))

// Hover on the "Updated on" text for each issue to see tooltip
// Issue 1: ref=e1308 - Updated on Oct 17, 2026 1h ago
// Issue 2: ref=e1341 - Updated on Oct 16, 2026 1d ago
// Issue 3: ref=e1372 - Updated on Oct 16, 2026 1d ago
// Issue 4: ref=e1405 - Updated on Oct 16, 2026 1d ago
// Issue 5: ref=e1441 - Updated on Oct 15, 2026 2d ago

// Hover on each one to check for tooltip
await page.hover({ ref: "e1308" })
await wait({ waitTime: 1.5 })
var tooltip1 = await page.snapshot()
console.log("--- After hover on #1 ---")
console.log(tooltip1.snapshot.grep("updated", { context: 5 }))

// Hover on issue 1's updated date
await page.hover({ ref: "e1308" })
await wait({ waitTime: 2 })
var snap1 = await page.snapshot()
console.log("=== Hover on #1 ===")
console.log(snap1.snapshot.grep("tooltip", { context: 2 }))

// Hover on issue 2's updated date
await page.hover({ ref: "e1341" })
await wait({ waitTime: 2 })
var snap2 = await page.snapshot()
console.log("=== Hover on #2 ===")
console.log(snap2.snapshot.grep("tooltip", { context: 2 }))

// Hover on issue 3's updated date
await page.hover({ ref: "e1372" })
await wait({ waitTime: 2 })
var snap3 = await page.snapshot()
console.log("=== Hover on #3 ===")
console.log(snap3.snapshot.grep("tooltip", { context: 2 }))

// Hover on issue 4's updated date
await page.hover({ ref: "e1405" })
await wait({ waitTime: 2 })
var snap4 = await page.snapshot()
console.log("=== Hover on #4 ===")
console.log(snap4.snapshot.grep("tooltip", { context: 2 }))

// Hover on issue 5's updated date
await page.hover({ ref: "e1441" })
await wait({ waitTime: 2 })
var snap5 = await page.snapshot()
console.log("=== Hover on #5 ===")
console.log(snap5.snapshot.grep("tooltip", { context: 2 }))
